INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'History', 'Unit 1', 'Molarum Grade 10 — History Unit 1: Development of Capitalism and Nationalism 1815 to 1914', 'Source-grounded Molarum Grade 10 History questions for Unit 1: Development of Capitalism and Nationalism 1815 to 1914.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('7c89fc0f-dd8b-4a2e-8f79-da02b873da47'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'Which feature of capitalism is emphasized in the textbook?', 'Most means of production are privately owned', 'The textbook explains that most means of production are privately owned in a capitalist system.', 0),('e5aded48-21f8-4cb6-8d8d-cd38fdf4c9f8'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'In which country did the Industrial Revolution first begin according to the textbook?', 'England', 'The source states that the Industrial Revolution first started in England in the eighteenth century.', 1),('6ac52887-1cc4-4efa-87cb-8708d215b91d'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'Which energy sources replaced wind and water power after the Industrial Revolution?', 'Coal and steam', 'The textbook identifies coal and steam as new sources of energy and power that replaced wind and water.', 2),('27706259-47f9-48be-89ba-58f2eb8eb044'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'What system replaced the domestic system during industrialization?', 'The factory system', 'The source says the factory system was created to replace domestic production in homes or workshops.', 3),('b00a6b5a-1e11-488a-8064-605dcf5a9b8a'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'What two social classes did industrialization especially promote?', 'The proletariat and bourgeoisie', 'The textbook identifies the proletariat and bourgeoisie as new socio-economic classes promoted by industrialization.', 4),('8933634b-eba7-47e9-8664-9ca2573972d5'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'In the capitalist system, what do proletarians receive for their labour?', 'Wages', 'The source states that proletarians receive wages for their labour.', 5),('52129839-28db-40a4-8e30-d5cfc1dd6856'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'What does the textbook call an economy in which government controls production, distribution, and prices?', 'A command economy', 'The source defines a command economy as one in which government controls production, distribution, and prices.', 6),('d9bbd6bc-2c78-44d6-8409-8258a026859e'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'How does the textbook define nationalism?', 'A feeling of belonging and loyalty to a nation', 'Nationalism is described as a feeling of belonging and loyalty that makes people think of themselves as a nation.', 7),('78ad9577-5b45-4809-8cfd-0d8b1dc12a2d'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'What was a main objective of the Treaty of Vienna in 1815?', 'To restore monarchies and reverse Napoleonic changes', 'Britain, Russia, Prussia, and Austria drew the Treaty of Vienna to reverse Napoleonic changes and restore monarchies.', 8),('40d83af1-cd19-4d2b-8bf8-160ae737aa6b'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'Which power occupied Lombardy and Venice before Italian unification?', 'Austria', 'Austrian occupation of Lombardy and Venice was listed as an obstacle to Italian unity.', 9),('ed0db1dd-c5d0-43a1-8761-a50c4ba1bd4a'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'Which movement did Giuseppe Mazzini found in 1831?', 'Young Italy', 'The source states that Mazzini founded Young Italy in 1831.', 10),('b5cb9ce6-6ba6-4da6-848f-529fc579c3d1'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'What position did Count Camillo di Cavour hold from 1852?', 'Prime minister of the Kingdom of Sardinia', 'Cavour became prime minister of the independent Kingdom of Sardinia in 1852.', 11),('e31d6d0a-c398-4a2c-8c6d-f15b74096357'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'What force did Giuseppe Garibaldi lead in southern Italy?', 'The Red Shirts', 'Garibaldi led the Red Shirts, who captured Sicily and moved into southern Italy.', 12),('cb36482f-ec86-45ed-817a-a695e7550b25'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'Who became king when the Kingdom of Italy was established in 1861?', 'Victor Emmanuel II', 'The textbook says Victor Emmanuel II became king when the Kingdom of Italy was established in 1861.', 13),('53172aaa-60e8-460d-868e-acfbcc7828aa'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'What was the Zollverein?', 'An economic alliance that removed tariffs between German states', 'The Zollverein was a customs union that promoted trade by removing tariffs among German states.', 14),('f09aefe8-bef3-445b-8fe7-f9610ec51589'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'Which policy referred to using military power to achieve German unification?', 'Blood and Iron', 'The source defines Bismarck’s Blood and Iron policy as using military power to achieve unification.', 15),('5c85c620-d50b-41fa-8a40-cf0a975936d3'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'Which three wars did Bismarck use in the unification of Germany?', 'Danish, Seven Weeks, and Franco-Prussian wars', 'The text lists the Danish War, Seven Weeks War, and Franco-Prussian War as the three wars of German unification.', 16),('876b4016-5b39-4237-80b3-ae8acc232079'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'Which groups fought in the American Civil War according to the textbook?', 'The Union and the Confederates', 'The war was fought between Northern States known as the Union and Southern States known as the Confederates.', 17),('987391c3-93e6-406c-81bd-ba7e3423894a'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'What issue was identified as the most important cause of the American Civil War?', 'Slavery', 'The source says conflict over slavery was the most important issue leading to the war.', 18),('190dc851-3ee3-4129-8a17-4b298499feff'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'multiple_choice', 'What combination created the Eastern Question?', 'Balkan nationalism, Ottoman decline, and competing Great Power interests', 'The Eastern Question arose from Balkan nationalism, the declining Ottoman Empire, and divergent interests of Great Powers.', 19),('e3e6d8f6-1a6b-42e9-855f-ab0e0039da98'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'true_false', 'Capitalist enterprises are mainly run by a command economic system.', 'False', 'Capitalism is distinguished from a command economy because its means of production are mainly privately owned and government interferes less.', 20),('6efc8ed4-0db6-4b51-8962-7fde67a553b8'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'true_false', 'Venetia became part of Italy after the defeat of Austria in the Seven Weeks War.', 'True', 'The text states that Italy got Venetia after Austria’s defeat in the Seven Weeks War.', 21),('a97102f7-eed7-4a16-82bd-14db693d3307'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'true_false', 'The Seven Weeks War excluded Austria from German affairs.', 'True', 'One listed result of the Seven Weeks War was Austria’s exclusion from German affairs.', 22),('c59a6813-c352-40b7-88f0-b046deb5ead2'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'true_false', 'Britain supported the Balkan nationalists because it wanted Russia in the Mediterranean.', 'False', 'Britain opposed Russian expansion into the Mediterranean and supported the Turks against nationalist movements.', 23),('1f6d6f22-0b84-4567-8b4b-149191a21e29'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'Name the two main classes the textbook associates with industrialization.', 'The proletariat and the bourgeoisie.', 'Industrialization promoted these two socio-economic classes in the textbook.', 24),('c07bbf46-6325-4945-859c-c647295dc940'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'State one movement before the nineteenth century that helped nationalist sentiment grow.', 'The Renaissance, the Protestant Revolution, or the expansion of commerce.', 'The textbook lists these movements as helping nationalist sentiment grow.', 25),('bce37b0b-4f55-41b0-8e87-18813e4f6eb6'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'Name one obstacle to Italian unity in 1815.', 'Austrian occupation of Lombardy and Venice, the Papal States, or the existence of several independent Italian states.', 'The textbook identifies all three as obstacles to Italian unification.', 26),('c2a3dfda-e59a-450c-8ebb-6eae78485225'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'What did Garibaldi do after his forces conquered southern Italy?', 'He agreed to unite with Piedmont-Sardinia and handed power to Victor Emmanuel II.', 'Garibaldi’s Red Shirts conquered southern areas before he handed power to Victor Emmanuel II.', 27),('9802caf8-b45d-478c-8cd4-233e3e35c6c7'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'What was realpolitik as described in the textbook?', 'Pursuing goals by any means necessary.', 'The source defines realpolitik as pursuing goals by any means necessary.', 28),('56599368-c8a4-4396-83f2-b5b3322a8ce7'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'Give one result of the Treaty of Frankfurt of 1871 for France.', 'France ceded Alsace and Lorraine to Germany or agreed to pay huge war indemnities to Germany.', 'The Treaty of Frankfurt required France to cede Alsace and Lorraine and pay large indemnities.', 29),('998e40cc-a2b1-4ba4-869c-b4ea60a59e50'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'Why did the Confederates want to keep slavery?', 'They saw slavery as the basis of their cotton-dependent southern economy.', 'The textbook connects the southern economy’s dependence on cotton with plantation owners’ support for slavery.', 30),('5e583acb-c1b7-45d8-8718-e4c5f61af241'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'Give one reason Russia supported Balkan nationalists.', 'Russia shared Slavic and Orthodox Christian ties with some Balkan peoples or wanted access to the Black Sea and Mediterranean Sea.', 'The source gives both cultural-religious ties and access to seas as reasons for Russian support.', 31),('0af4af4b-c278-4d07-8433-6beed7b27d9a'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'In what year did Italians enter Rome and finalize Italian unification?', '1870', 'The text states that Italians entered Rome in 1870, finalizing Italian unification.', 32),('d7c8a020-495c-436c-8fb3-b8b0fdb08971'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'In what year was the Treaty of Vienna drawn?', '1815', 'The source dates the Treaty of Vienna to 1815.', 33),('88e359d0-1a41-43bf-8f2a-c19ea9831a27'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'In what year did Mazzini found Young Italy?', '1831', 'Mazzini founded Young Italy in 1831.', 34),('cac62f81-f0c9-46e0-8abf-3ea554f062e8'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'In what year was the Kingdom of Italy established?', '1861', 'The textbook states that the Kingdom of Italy was established in 1861.', 35),('7ecee759-1fcd-4983-8c59-1b254546883f'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'In what year did the Seven Weeks War take place?', '1866', 'The source identifies the Austro-Prussian conflict as the Seven Weeks War of 1866.', 36),('d5294a03-2b45-478e-8293-e0e763b4cede'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'In what year was the German Empire proclaimed at Versailles?', '1871', 'The German Empire was proclaimed in 1871 at the Palace of Versailles.', 37),('814e006e-4e5f-4541-8d0b-202efee2c279'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'In what year did the Thirteenth Amendment officially outlaw slavery according to the textbook?', '1865', 'The source says the Thirteenth Amendment was adopted on December 6, 1865.', 38),('d6331fc0-0efd-4135-8d01-c46c9ac9900c'::uuid, '1a5d3211-1430-4bcb-8e82-a753b1186460'::uuid, 'fill_blank', 'In what year did Romania, Montenegro, and Serbia gain independence according to the textbook?', '1878', 'The source states that Romania, Montenegro, and Serbia gained independence in 1878.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('47bf5475-fcfe-4ea3-801e-90c37639b57a'::uuid, '7c89fc0f-dd8b-4a2e-8f79-da02b873da47'::uuid, 'Most means of production are privately owned', TRUE, 0),('b2c48012-0cc1-4533-8037-5555a1de3a43'::uuid, '7c89fc0f-dd8b-4a2e-8f79-da02b873da47'::uuid, 'All production is controlled by government', FALSE, 1),('7ebd404b-be20-41f8-8235-306a882fcf5f'::uuid, '7c89fc0f-dd8b-4a2e-8f79-da02b873da47'::uuid, 'Prices are fixed by a central plan', FALSE, 2),('e42e8f60-195a-4a7f-8ff8-2474da2e5e62'::uuid, '7c89fc0f-dd8b-4a2e-8f79-da02b873da47'::uuid, 'Land is owned only by workers', FALSE, 3),('d330be59-77c1-4548-87b1-6badb942efc8'::uuid, 'e5aded48-21f8-4cb6-8d8d-cd38fdf4c9f8'::uuid, 'England', TRUE, 0),('7e1a19ff-3895-4ee5-8caa-f9f2db70173e'::uuid, 'e5aded48-21f8-4cb6-8d8d-cd38fdf4c9f8'::uuid, 'France', FALSE, 1),('b96086a5-19bf-4c1e-853f-12db09d3dea8'::uuid, 'e5aded48-21f8-4cb6-8d8d-cd38fdf4c9f8'::uuid, 'Germany', FALSE, 2),('c390c535-0e7c-4c74-8a10-c748d5a88665'::uuid, 'e5aded48-21f8-4cb6-8d8d-cd38fdf4c9f8'::uuid, 'Italy', FALSE, 3),('294c4e64-9ff1-4bc7-8eb6-addba139fc42'::uuid, '6ac52887-1cc4-4efa-87cb-8708d215b91d'::uuid, 'Coal and steam', TRUE, 0),('39439dde-3625-4577-885d-2b6ec8a847f7'::uuid, '6ac52887-1cc4-4efa-87cb-8708d215b91d'::uuid, 'Oil and electricity', FALSE, 1),('026f6ae5-36a0-434a-8a9c-5dda739156e9'::uuid, '6ac52887-1cc4-4efa-87cb-8708d215b91d'::uuid, 'Wood and solar power', FALSE, 2),('e513b698-5b68-41f9-8699-4c981c8354a1'::uuid, '6ac52887-1cc4-4efa-87cb-8708d215b91d'::uuid, 'Gas and nuclear power', FALSE, 3),('6d62afd9-ba55-414b-8b83-a9e8166062d0'::uuid, '27706259-47f9-48be-89ba-58f2eb8eb044'::uuid, 'The factory system', TRUE, 0),('10113a41-a339-4b72-8cd1-e2a1d1ccc3c5'::uuid, '27706259-47f9-48be-89ba-58f2eb8eb044'::uuid, 'The barter system', FALSE, 1),('279e6fda-6605-4f19-8ed7-0b2d7cb53faf'::uuid, '27706259-47f9-48be-89ba-58f2eb8eb044'::uuid, 'The command system', FALSE, 2),('281b71